<template>
<header class="topbar"><div class="bar"><a class="brand" href="/agent/index"><span class="mark">智</span>智聘 AI</a><span class="user">高级产品经理 · 面试入场</span></div></header><main class="main"><a class="crumb" href="/agent/application-detail?id=ai-product">投递详情 / 面试入场准备</a><section class="head"><h1>进入面试前，请完成设备检测</h1><p>高级产品经理（AI 招聘方向） · 06月18日 14:30 - 15:30 · AI + HR 协同面试</p></section><div class="layout"><section class="card"><h2>设备与网络状态</h2><div class="checks"><div class="check" id="cameraCheck"><span class="check-icon">⌕</span><div><strong>摄像头</strong><small id="cameraDetail">尚未检测，请点击右侧按钮开启</small></div><span class="state" id="cameraState">待检测</span></div><div class="check" id="micCheck"><span class="check-icon">♩</span><div><strong>麦克风</strong><small id="micDetail">尚未检测，请点击右侧按钮授权</small></div><span class="state" id="micState">待检测</span></div><div class="check ok"><span class="check-icon">✓</span><div><strong>网络连接</strong><small>延迟 42ms · 可用带宽 18.6Mbps</small></div><span class="state">良好</span></div></div><div class="action-row"><button class="retry" id="retry">重新检测</button><button class="enter" id="enter" disabled>准备就绪，进入面试</button></div></section><aside class="card"><h2>摄像头预览</h2><div class="video"><video id="preview" autoplay playsinline muted></video><div class="video-empty" id="empty">点击下方按钮后开启预览<span>仅用于本机检测，不会自动录制</span></div></div><button class="camera" id="camera">开启摄像头和麦克风</button><div class="token">会话已验证 · Token 有效至 06月18日 15:40</div><label class="consent"><input id="agree" type="checkbox"><span>我已阅读面试须知，允许本次面试使用音视频设备。</span></label></aside></div></main><div class="toast" id="toast"></div>
</template>

<script setup>
import { onMounted } from 'vue'

onMounted(() => {
  let stream=null,cameraOk=false,micOk=false;const preview=document.getElementById('preview'),empty=document.getElementById('empty'),camera=document.getElementById('camera'),enter=document.getElementById('enter'),agree=document.getElementById('agree'),toast=document.getElementById('toast');function update(){document.getElementById('cameraCheck').className='check '+(cameraOk?'ok':'');document.getElementById('micCheck').className='check '+(micOk?'ok':'');document.getElementById('cameraState').textContent=cameraOk?'正常':'待检测';document.getElementById('micState').textContent=micOk?'正常':'待检测';document.getElementById('cameraDetail').textContent=cameraOk?'已获得摄像头权限，画面清晰':'尚未检测，请点击右侧按钮开启';document.getElementById('micDetail').textContent=micOk?'已检测到麦克风输入':'尚未检测，请点击右侧按钮授权';enter.disabled=!(cameraOk&&micOk&&agree.checked)}async function detect(){if(!navigator.mediaDevices?.getUserMedia){show('当前浏览器不支持设备检测');return}try{stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});preview.srcObject=stream;preview.style.display='block';empty.style.display='none';cameraOk=micOk=true;camera.textContent='关闭设备预览';update();show('摄像头和麦克风检测通过')}catch(e){cameraOk=false;micOk=false;update();show(e.name==='NotAllowedError'?'未获得设备权限，请在浏览器地址栏允许访问':'设备暂时不可用，请检查连接')}}function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;preview.srcObject=null;preview.style.display='none';empty.style.display='grid';camera.textContent='开启摄像头和麦克风';cameraOk=micOk=false;update()}camera.onclick=()=>stream?stop():detect();document.getElementById('retry').onclick=()=>{stop();detect()};agree.onchange=update;enter.onclick=()=>{localStorage.setItem('interviewReady','1');stream?.getTracks().forEach(t=>t.stop());window.__agentNavigate('/agent/interview-room?job=ai-product');};function show(t){toast.textContent=t;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2400)}update();
})
</script>

<style>
