;margin-top:2px;color:var(--muted);font-size:11px}.state{padding:3px 7px;border-radius:5px;color:var(--b);background:var(--soft);font-size:10px;font-weight:700}.check.ok .state{color:var(--green);background:var(--greenbg)}.check.warn .state{color:var(--orange);background:var(--orangebg)}.action-row{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:19px}.retry,.enter{height:41px;padding:0 17px;border:0;border-radius:8px;font-weight:800;cursor:pointer}.retry{color:var(--b);background:var(--soft)}.enter{color:#fff;background:var(--b)}.enter:disabled{opacity:.5;cursor:not-allowed}.notice{padding:13px;border-radius:8px;color:#52647D;background:#F6F9FD;font-size:12px}.notice strong{display:block;margin-bottom:5px;color:var(--p)}.consent{display:flex;gap:8px;margin-top:17px;color:var(--muted);font-size:12px}.consent input{width:16px;height:16px;margin-top:3px}.video{position:relative;overflow:hidden;aspect-ratio:16/9;margin-top:15px;border-radius:9px;background:#102D53}.video video{width:100%;height:100%;object-fit:cover;display:none}.video-empty{position:absolute;inset:0;display:grid;place-items:center;color:#C8D6E8;text-align:center;font-size:12px}.video-empty span{display:block;margin-top:4px;color:#A9BCD5}.camera{width:100%;height:39px;margin-top:11px;border:0;border-radius:7px;color:#fff;background:var(--b);font-weight:800;cursor:pointer}.token{margin-top:14px;color:#93A1B2;font-size:11px}.toast{position:fixed;right:22px;bottom:22px;padding:11px 15px;border-radius:8px;color:#176B50;background:#F2FBF7;display:none}.toast.show{display:block}@media(max-width:760px){.bar,.main{width:calc(100% - 28px)}.topbar{height:64px}.layout{grid-template-columns:1fr}.head{padding:19px}.action-row{align-items:stretch;flex-direction:column}.retry,.enter{width:100%}}
